mapper.select:
select sc.id , sc.name, sc.code, sc.company_type, sc.industry_field, sc.company_taxes_type, sc.enterprise_size, sc.house_count, sc.address, sc.contacts, sc.tel, sc.create_time, sc.park_org_id, sc.licenses, sc.source, sc.status, sp.org_name parkOrgName from sys_company sc left join sys_organization sp on sp.id = sc.park_org_id
sc.deleted = 0
and sc.name like "%"#{name}"%"
and sc.park_org_id= #{parkOrgId}
and sc.code= #{code}
and sc.company_type = #{companyType}
and sc.status = #{status}
and sc.park_org_id in
#{parkOrgId}
order by sc.create_time desc
